/**
 * Gmail Node - Version 2.2
 * Discriminator: resource=message, operation=get
 */


interface Credentials {
  googleApi: CredentialReference;
  gmailOAuth2: CredentialReference;
}

export type GmailV22MessageGetParams = {
  resource: 'message';
  operation: 'get';
  authentication?: 'oAuth2' | 'serviceAccount' | Expression<string>;
/**
 * Message ID
 */
    messageId: string | Expression<string>;
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @builderHint Keep true by default. True returns one flat item for each message. The sender is the string `$json.From`, for example "Sara Chen &lt;sara@example.com&gt;". The item also has `To`, `Cc`, `Bcc`, `Subject`, `snippet`, `labels`, `id` and `threadId`. It has no message body. False returns the parsed email. The sender is the object `$json.from`: read the address with `$json.from.value[0].address`, or parse the full header line `$json.headers.from`, for example "From: Sara Chen &lt;sara@example.com&gt;". The body is in `$json.text`, `$json.html` and `$json.textAsHtml`. With false, `$json.From` is undefined. With either setting, `$json.from` is not a string. To filter or route by sender, keep true. Set false only when the workflow needs the message body or the attachments, for example for AI classification or summarization. To get the attachments, also turn on the `downloadAttachments` option. False uses much more memory and often causes out-of-memory crashes.
 * @default true
 */
    simple?: boolean | Expression<boolean>;
/**
 * Options
 * @displayOptions.hide { simple: [true] }
 * @default {}
 */
    options?: {
    /** Prefix for name of the binary property to which to write the attachment. An index starting with 0 will be added. So if name is 'attachment_' the first attachment is saved to 'attachment_0'.
     * @default attachment_
     */
    dataPropertyAttachmentsPrefixName?: string | Expression<string>;
    /** Whether the email's attachments will be downloaded and included in the output
     * @default false
     */
    downloadAttachments?: boolean | Expression<boolean>;
  };
};

